import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')

    # If opponent has been extremely cooperative, reciprocate.
    if opp_c >= n - 2 and opp_last == 'C':
        return 'C'

    # If opponent has been extremely defection-heavy, resist.
    if opp_c <= 2 and n >= 8:
        return 'D'

    # Detect streaks.
    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    # Against long defection streak, occasionally test cooperation.
    if opp_last == 'D' and same_count >= 4:
        if rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    # Against long cooperation streak, mostly cooperate but occasionally probe.
    if opp_last == 'C' and same_count >= 5:
        if n < 90 and rng.randint(0, 9) == 0:
            return 'D'
        return 'C'

    # Tit-for-tat-like core with forgiveness.
    if opp_last == 'C':
        if my_last == 'D' and n < 95 and rng.randint(0, 4) == 0:
            return 'D'
        return 'C'
    else:
        if n < 95 and rng.randint(0, 6) == 0:
            return 'C'
        return 'D'
